# Generated by manage.py generate_test_cases.
from types import SimpleNamespace
from unittest.mock import Mock, call, patch

from bloomerp.automation.actions.send_email import SendEmailExecutor, SendEmailForm
from bloomerp.communication.emails.registry import EMAIL_PROVIDER_REGISTRY
from bloomerp.models.communication.email_account import EmailAccount
from bloomerp.tests.base import (
    BloomerpWorkflowNodeTestCase,
    WorkflowNodeScenario,
)
from bloomerp.widgets.text_editor import BloomerpTextEditorWidget


class TestSendEmailNode(BloomerpWorkflowNodeTestCase):
    node_id = 'SEND_EMAIL'
    executor_class = SendEmailExecutor

    def get_test_scenarios(self) -> list[WorkflowNodeScenario]:
        """Describe sending the saved rich text body with resolved references."""
        return [
            WorkflowNodeScenario(
                name="Sends saved editor HTML as the email body",
                parameters={
                    "from_account": "1",
                    "recipient": "{{ input.recipient }}",
                    "subject": "Welcome",
                    "body": "<p>Hello <strong>{{ input.name }}</strong></p>",
                    "body_format": "html",
                },
                trigger_data={"recipient": "alice@example.com", "name": "Alice"},
                expected_output={
                    "recipient": "alice@example.com",
                    "name": "Alice",
                    "email": {
                        "recipient": "alice@example.com",
                        "subject": "Welcome",
                        "body": "<p>Hello <strong>Alice</strong></p>",
                        "status": "sent",
                    },
                },
            ),
            WorkflowNodeScenario(
                name="Escapes dynamic values in an HTML email",
                parameters={
                    "from_account": "1",
                    "recipient": "alice@example.com",
                    "subject": "Welcome",
                    "body": '<p>Hello <strong>{{ input.name }}</strong></p>',
                    "body_format": "html",
                },
                trigger_data={"name": '</p><a href="https://example.com">Pay here</a>'},
                expected_output={
                    "name": '</p><a href="https://example.com">Pay here</a>',
                    "email": {
                        "recipient": "alice@example.com",
                        "subject": "Welcome",
                        "body": (
                            '<p>Hello <strong>&lt;/p&gt;&lt;a href=&quot;'
                            'https://example.com&quot;&gt;Pay here&lt;/a&gt;</strong></p>'
                        ),
                        "status": "sent",
                    },
                },
            ),
            WorkflowNodeScenario(
                name="Preserves existing unmarked plain-text emails",
                parameters={
                    "from_account": "1",
                    "recipient": "alice@example.com",
                    "subject": "Welcome",
                    "body": "First line\nUse <example> literally",
                },
                expected_output={
                    "email": {
                        "recipient": "alice@example.com",
                        "subject": "Welcome",
                        "body": "First line\nUse <example> literally",
                        "status": "sent",
                    },
                },
            ),
        ]

    def test_workflow_node_simulations(self) -> None:
        """
        Use case: Execute an email node configured with rich text.
        Expected result: The provider receives the resolved HTML body.
        """
        # 1. Replace the external email provider while running the node scenario.
        adapter = Mock()
        provider = SimpleNamespace(adapter_class=Mock(return_value=adapter))
        account = SimpleNamespace(provider="test")
        with (
            patch.object(EmailAccount.objects, "get", return_value=account),
            patch.object(EMAIL_PROVIDER_REGISTRY, "get", return_value=provider),
        ):
            super().test_workflow_node_simulations()

        # 2. Check HTML escaping and the legacy plain-text provider calls.
        self.assertEqual(adapter.send_email.call_args_list, [
            call(
                to=["alice@example.com"],
                subject="Welcome",
                body_text=None,
                body_html="<p>Hello <strong>Alice</strong></p>",
            ),
            call(
                to=["alice@example.com"],
                subject="Welcome",
                body_text=None,
                body_html=(
                    '<p>Hello <strong>&lt;/p&gt;&lt;a href=&quot;'
                    'https://example.com&quot;&gt;Pay here&lt;/a&gt;</strong></p>'
                ),
            ),
            call(
                to=["alice@example.com"],
                subject="Welcome",
                body_text="First line\nUse <example> literally",
                body_html=None,
            ),
        ])

    def test_body_form_round_trips_rich_text(self) -> None:
        """
        Use case: Reopen and submit an email node with formatted content.
        Expected result: The editor retains the saved HTML in its form value.
        """
        # 1. Render the configured body through the workflow form's widget.
        body = "<p>Hello <strong>Alice</strong></p>"
        form = SendEmailForm(initial={"body": body, "body_format": "html"})
        self.assertIsInstance(form.fields["body"].widget, BloomerpTextEditorWidget)
        rendered_body = str(form["body"])
        self.assertIn('data-text-editor-input="true"', rendered_body)
        self.assertIn('name="body"', rendered_body)
        self.assertIn('&lt;strong&gt;Alice&lt;/strong&gt;', rendered_body)
        self.assertEqual(form["body_format"].value(), "html")

        # 2. Submit the editor's hidden input value and confirm it survives cleaning.
        submitted = SendEmailForm(data={
            "from_account": "1",
            "recipient": "alice@example.com",
            "subject": "Welcome",
            "body": body,
            "body_format": "html",
        })
        self.assertTrue(submitted.is_valid(), submitted.errors)
        self.assertEqual(submitted.cleaned_data["body"], body)
        self.assertEqual(submitted.cleaned_data["body_format"], "html")

    def test_legacy_body_opens_as_safe_editor_html(self) -> None:
        """
        Use case: Open an unmarked plain-text node in the rich text editor.
        Expected result: Lines and literal angle brackets remain visible.
        """
        # 1. Open both unmarked and explicitly plain-text configurations.
        for initial in (
            {"body": "First line\nUse <example> literally"},
            {"body": "First line\nUse <example> literally", "body_format": "plain"},
        ):
            with self.subTest(initial=initial):
                form = SendEmailForm(initial=initial)

                # 2. Confirm the editor value is safe HTML for the next save.
                self.assertEqual(
                    form["body"].value(),
                    "<p>First line<br>Use &lt;example&gt; literally</p>",
                )
                self.assertEqual(form["body_format"].value(), "html")
